// TH14 synthetic bullet aliases used by this card (transcribe/th14/bullet-types.md).
// Native type5 keeps the same modern slot; mapping is synthetic, not byte-identical assets.
const TH14_BALL2: int = 432;

// TH14 v1.00b Stage 1 midboss wave, st01.ecl.txt:867-883 (MainSub03 / MainSub03b).
// Source t0 is this card's phase start; the 120-frame shell buffer precedes the source wave.
// Two schedules: right line (x=+224) starts at t0 (MainSub03b async), left line (x=-224)
// starts at t0+120 (MainSub03 wait(120) before its own loop). Each line is 6 red/blue
// pairs, one pair every 60 frames; last spawn at source 330 (right) / 450 (left).
// GirlA01c closure st01.ecl.txt:127-156, at-attack st01.ecl.txt:34-80.
// DeadAttack1/DeadAttackEt1 (default.ecl.txt:53-92) are the Lunatic setDeath callback:
// the invincible no-DPS shell never kills these enemies, so per the approved card policy
// no timed death volley is synthesized.
const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;
const BAM_PER_DEG: int = 182; // 65536/360: one source mode7 degree per frame

// GirlA01_at: one aimed type5/color6 bullet per burst, fired from the fairy position.
// RAND%300 (E/N) or RAND%60 (H/L); speed 1.2/1.2/2.4/4.0; bursts 1/1/5/10;
// burst interval 30/30/60/60. Source birth ANIM EX (type2 a=1) omitted by policy.
async sub girl_at() {
    var rank: int = global(GVAR_RANK);
    var bursts: int = 1;
    var interval: int = 30;
    var speed: fx = 1.2fx;
    if rank == RANK_HARD {
        bursts = 5;
        interval = 60;
        speed = 2.4fx;
        wait(rand(60));
    } else if rank == RANK_LUNATIC {
        bursts = 10;
        interval = 60;
        speed = 4fx;
        wait(rand(60));
    } else {
        wait(rand(300));
    }
    for i in 0..bursts {
        _ = fire(TH14_BALL2, 6, $self_x, $self_y, speed, aim_player(), none, none);
        wait(interval);
    }
}

// GirlA01c body. side 0 = source x=-224 (no mirror), side 1 = x=+224 (source
// moveSetMirror(1)); the mirror is folded into the physical angle because the target
// has no mirror flag. HP, boxes and mirror are set per creation, nothing inherited.
async sub girl(side: int) {
    set_invuln(65535);
    set_hurtbox(12fx); // setHurtbox(24,24): circular branch radius 24/2
    set_hitbox(8fx);   // setHitbox(16,16): circular branch radius 16/2
    var base: angle = 0deg;
    if side == 1 { base = 180deg; }
    move_vel(0, base, 4fx, EASE_LINEAR);  // moveVel(0, 4.0)
    move_speed(60, 2.4fx, EASE_LINEAR);   // moveSpeedTime(60, 0, 2.4)
    wait(10);
    wait(50);
    if global(GVAR_RANK) >= RANK_NORMAL {
        spawn girl_at();                  // !NHL @GirlA01_at() async
    }
    // moveAngleTime(160, 7, 1deg) + moveSpeedTime(100, 1, 1.4) run together.
    // mode7 is a fixed per-frame angle increment; explicit loop state reproduces it.
    var t: int = 0;
    while t < 160 {
        var ang: angle = (t * BAM_PER_DEG) as angle;
        if side == 1 { ang = (32768 - t * BAM_PER_DEG) as angle; }
        var spd: fx = 1.4fx;
        if t < 100 { spd = 2.4fx - ((t * t) as fx) / 10000fx; } // mode1 t^2: 2.4 -> 1.4
        move_vel(0, ang, spd, EASE_LINEAR);
        wait(1);
        t = t + 1;
    }
    wait(120);
    loop { wait(1); }
}

// One side's spawn line: 6 x (red at +0, blue at +30), 60-frame group period.
sub line(x: fx, side: int) {
    for i in 0..6 {
        _ = spawn_enemy(x, 64fx, 80, 0, 1000, 0, girl(side));
        wait(30);
        _ = spawn_enemy(x, 64fx, 80, 0, 1000, 0, girl(side));
        wait(30);
    }
}

async sub right_line() {
    line(224fx, 1);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn right_line(); // MainSub03b async at entry
    wait(120);          // MainSub03 wait(120) before its own line
    line(-224fx, 0);
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
